Translate("ruRU", "arathi-basin", {
	title = "Низина Арати",
	sections = {
		{
			title = "Обзор",
			text = [=[Низина Арати — долина в кольце гор в сердце нагорья, одна из самых плодородных земель {link:eastern-kingdoms}Восточных королевств{/link}. Ее ферма, рудник, лесопилка, кузница и стойла строились, чтобы кормить королевство. Теперь за них бьются два войска. {link:league-of-arathor}Лига Аратора{/link} удерживает Зал Троллебоя и намерена завоевать богатства низины для {link:stormwind-city}Штормград{/link}а и {link:alliance}Альянса{/link}. {link:defilers}Осквернители{/link} из числа Отрекшихся удерживают Логово Осквернителя и намерены отрезать людей от их союзников-{link:dwarves}дворф{/link}ов на юге. Их дороги ведут из Опорного пункта и из Павшего Молота.]=],
		},
	},
})

Translate("ruRU", "captain-nials", {
	title = "Капитан Ниалс",
	subtitle = "Командир Опорного пункта",
	found = "Опорный пункт",
	hint = [=[Поговорите с капитаном, которая командует лагерем в Опорном пункте.]=],
	allegiance = "Королевство Стромгард · Альянс",
	aliases = { "Ниалс" },
	sections = {
		{
			title = "Обзор",
			text = [=[Капитан Ниалс командует солдатами {link:stromgarde-keep}Стромгард{/link}а в Опорном пункте. У нее нет города, который нужно защищать, — есть лишь надежда отвоевать его. Ее войско тает, а враги множатся, и каждую неделю {link:ogres}огр{/link}ы, {link:syndicate}Синдикат{/link} и ее собственное ополчение бьются в руинах столицы, и равновесие сил обходится все большей кровью.]=],
		},
		{
			title = "Значение",
			text = [=[Ниалс — голос королевства, которое отказывается умирать. Когда {link:dwarves}дворф{/link}ы Моста Тандола умоляли ее прислать солдат, она отказала им, скорбя. Честь, сказала она, держит ее войско на нагорье, пока королевское знамя вновь не поднимется над {link:stromgarde-keep}Стромгард{/link}ом.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она посылает бойцов против {link:syndicate}Синдикат{/link}а в {link:northfold-manor}Северное поместье{/link}, чтобы дороги снабжения из {link:southshore}Южнобережья{/link} оставались открытыми.
• Она платит за значки павших ополченцев, отнятые у Синдиката, чтобы семьи погибших узнали об их участи.
• В ее руках награды, назначенные за чернокнижницу Синдиката {link:marez-cowl}Марез Каул{/link}, за лорда {link:lord-falconcrest}Фальконкрест{/link}а и за его телохранителя {link:ott}Отт{/link}о.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Записи Опорного пункта называют лишь ее звание и ее дела. О ее жизни до падения города не написано ничего.]=],
		},
	},
	chapters = {
		{
			title = "Мольба с Моста",
			hint = "Доставьте в Опорный пункт мольбу дворфов Болотины.",
			text = [=[{link:dwarves}Дворфы{/link} {link:dun-modr}Дун Модр{/link}а потеряли свой город и половину своего моста и послали в {link:refuge-pointe}Опорный пункт{/link} за помощью. Ниалс выслушала вести о Мосте Тандола с тяжелым сердцем. Но дать ей было нечего. {link:stromgarde-keep}Стромгард{/link} пал, и каждый ее меч был нужен, чтобы вернуть его. Она велела передать, что дворфам придется выстоять в одиночку.]=],
		},
		{
			title = "Значки павших",
			hint = [=[Верните то, что Синдикат забирает у мертвых воинов Стромгарда.]=],
			text = [=[{link:syndicate}Синдикат{/link} платит своему сброду золотом за каждый значок {link:stromgarde-keep}Стромгард{/link}а, срезанный с убитого ополченца. Ниалс не желала, чтобы разбойники наживались на ее мертвых. Когда значки вернулись, она не развесила их как трофеи. Она послала каждой семье весть, что их солдат пал в бою, ибо считала, что горькая весть милосерднее молчания.]=],
		},
	},
	mentions = {
		{
			text = [=[«Обращение к {link:alliance}Альянс{/link}у», просьба {link:dwarves}дворф{/link}ов]=],
		},
		{ text = "«{link:northfold-manor}Северное поместье{/link}»" },
		{ text = "«Знаки {link:stromgarde-keep}Стромгард{/link}а»" },
		{ text = "«Разыскивается! {link:marez-cowl}Марез Каул{/link}»" },
		{
			text = [=[«Разыскивается! {link:ott}Отт{/link}о и {link:lord-falconcrest}Фальконкрест{/link}»]=],
		},
	},
	bonds = {
		{ id = "rhag-garmason", name = "Раг Гармасон", note = "просил у нее солдат" },
		{ id = "longbraid-the-grim", name = "Длиннокос Мрачный", note = "дворф, которому она не смогла помочь" },
		{ id = "lord-falconcrest", name = "Лорд Фальконкрест", note = "враг, за голову которого назначена награда" },
		{ id = "marez-cowl", name = "Марез Каул", note = "враг, за голову которой назначена награда" },
		{ id = "prince-galen-trollbane", name = "Принц Гален Троллебой", note = "ее принц в руинах" },
	},
})

