})

Translate("ruRU", "prince-galen-trollbane", {
	title = "Принц Гален Троллебой",
	subtitle = "Наследник Стромгарда",
	found = "Часовня в квартале защитников Крепости Стромгард",
	hint = [=[Отыщите принца, который удерживает последний квартал Стромгарда.]=],
	allegiance = "Королевство Стромгард",
	aliases = { "Гален Троллебой", "Гален" },
	sections = {
		{
			title = "Обзор",
			text = [=[Принц Гален Троллебой — сын короля {link:thoras-trollbane}Торас{/link}а и наследник павшего трона. Он удерживает последний угол {link:stromgarde-keep}Стромгард{/link}а, что еще принадлежит ему, — район старого города вокруг часовни. За этой часовней п{link:ogres}огр{/link}ебен его отец. Гален стережет гробницу, и он стережет меч, что лежит в ней.]=],
		},
		{
			title = "Значение",
			text = [=[Гален — последний из рода Троллебоев на нагорье, рода, чей основатель Игней добыл меч {link:trol-kalar}Трол'калар{/link} в битвах с троллями. Для троллей Орды его кровь — древний враг. Для его солдат он — все, что осталось от их короля.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он запечатал гробницу отца печатями и разделил их между уцелевшими воинами {link:stromgarde-keep}Стромгард{/link}а.
• Он разбил Печать {link:thoradin}Торадин{/link}а на куски и раздал их своим защитникам.
• Он отдал Печать {link:arathor}Аратор{/link}а лейтенанту Зову Доблести, а Печать Троллебоя хранит сам.
• Он посылает остатки своей конницы в разъезды по нагорью.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись этих дней не сообщает, как умер {link:thoras-trollbane}король Торас{/link} и как его сын стал править вместо него.]=],
		},
	},
	chapters = {
		{
