Translate("ruRU", "zengu", {
	title = "Зенгу",
	subtitle = "Охотник племени Черного Копья",
	found = "Павший Молот",
	hint = [=[Поговорите с охотником Черного Копья, который прибыл в Павший Молот с поручением.]=],
