		{ text = "«{link:trol-kalar}Трол'калар{/link}»" },
		{ text = "«{link:trol-kalar}Трол'калар{/link}»" },
	},
	bonds = {
		{ id = "vol-jin", name = "Вол'джин", note = "послал его" },
