Translate("ruRU", "myzrael", {
	title = "Мизраэль",
	subtitle = "Принцесса земли",
	found = "Под Нагорьем Арати; она говорит через Осколки Мизраэль",
	hint = [=[Прислушайтесь к голосу, который молит сквозь кристалл в северных горах.]=],
	allegiance = "Сама себе · ей служит Сумеречный Молот",
	sections = {
		{
			title = "Обзор",
			text = [=[Мизраэль — существо земных глубин, что лежит связанным под Нагорьем {link:arathi-highlands}Арати{/link}. Она называет себя принцессой земли. Великаны заковали ее там, и четыре камня Обуздания держат ее прикованной. Лишь через осколки кристалла может она говорить с миром наверху, и говорит она сладко, моля о спасении.]=],
		},
		{
			title = "Значение",
			text = [=[Мизраэль — тайна нагорья. {link:twilight-s-hammer}Сумеречный Молот{/link} называет ее Госпожой и трудится ради ее возвращения. Тот, кто бежал из их ордена с ее свитком, считает, что великаны связали ее не без причины и что ей ни в коем случае нельзя дать набраться сил.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она взывает к путникам в видениях через осколок своего кристалла.
• Она посылает их пробудить осколки, которые стерегут {link:kobolds}кобольд{/link}ы-{link:drywhisker-kobolds}Сухоусы{/link}.
• Она просит три ключа камней Обуздания и Жезл Порядка, который носит каменный страж {link:fozruk}Фозрук{/link}.
• Она называет своих союзников в {link:ironforge}Стальгорн{/link}е и в Павшем Молоте.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись {link:azeroth}Азерот{/link}а не говорит о существе по имени Мизраэль. Что она такое, откуда пришла и почему великаны связали ее — известно лишь с ее собственных слов и со слов безумца {link:theldurin-the-lost}Тельдурин{/link}а Заблудшего.]=],
		},
	},
	chapters = {
		{
			title = "Голос в кристалле",
			hint = [=[Откликнитесь на мольбу, которая исходит из кристалла в северных горах.]=],
			text = [=[Осколок запульсировал в руке, и пришло видение кристалла в северных горах. Там голос назвал свое имя: Мизраэль, заточенная великанами глубоко внизу. Она просила о помощи, и просила кротко.]=],
		},
		{
			title = "Свободна",
			hint = "Откройте Краеугольный камень во Внутреннем Круге Обуздания.",
			text = [=[Когда Жезл Порядка повернулся в Краеугольном камне, земля содрогнулась. Мизраэль вскричала, что она свободна. Встречаться со своими тюремщиками она пока не собиралась. Она скроется, наберется сил и однажды заставит великанов заплатить за их надзор. Когда она будет готова, ее нужно будет призвать.]=],
		},
		{
			title = "Оковы",
			hint = "Узнайте то, что знает безумный хранитель свитка.",
			text = [=[{link:theldurin-the-lost}Тельдурин Заблудший{/link} украл свиток пленницы Мизраэль и прочел его. Ее нужно призвать и одолеть, пока она не собрала свою силу, сказал он, и вновь связать ее же собственными зловещими оковами. Когда оковы сомкнулись вокруг осколков, далеко внизу поднялся крик, а затем рев. Прежде осколки были теплыми на ощупь. Теперь от них исходила лишь угроза.]=],
		},
	},
	mentions = {
		{ text = "«Кристалл в горах»" },
		{ text = "«Принцесса в ловушке»" },
		{ text = "«Камни Обуздания»" },
		{ text = "«Разрушение краеугольного камня»" },
		{ text = "«Союзники Мизраэль»" },
		{ text = "«Союзники Мизраэль»" },
		{ text = "«{link:theldurin-the-lost}Тельдурин Заблудший{/link}»" },
		{ text = "«Призыв принцессы»" },
	},
	bonds = {
		{ id = "zaruk", name = "Зарук", note = "служит ей в Павшем Молоте" },
		{ id = "gerrig-bonegrip", name = "Герриг Костехват", note = "служит ей в Стальгорне" },
		{ id = "fozruk", name = "Фозрук", note = "один из ее пленителей" },
		{ id = "theldurin-the-lost", name = "Тельдурин Заблудший", note = "бежал с ее свитком" },
	},
})

Translate("ruRU", "thoradin", {
	title = "Торадин",
	subtitle = "Первый король Аратора",
	allegiance = "Племя Арати · Аратор",
	sections = {
		{
			title = "Обзор",
			text = [=[Торадин был военным вождем племени {link:arathi-highlands}Арати{/link}, который сделал человечество единым народом. В эпоху, когда людские племена севера бились друг с другом, а тролли охотились на них всех, он связал их под одним знаменем. Он назвал новую державу {link:arathor}Аратор{/link} и воздвиг ее столицу, {link:stromgarde-keep}Стром{/link}, на нагорье, что носит имя его племени. Каждое человеческое королевство наших дней ведет начало от его труда.]=],
		},
		{
			title = "Значение",
			text = [=[До него были племена. После него был народ. Его союз с эльфами принес победу в {link:troll-wars}Войнах с троллями{/link} и дал человечеству знание магии, а его род эльфы {link:quel-thalas}Кель'Таласа{/link} чтили тысячи лет. Великая стена между нагорьем и {link:hillsbrad-foothills}Хилсбрад{/link}ом до сих пор носит его имя.]=],
		},
		{
			title = "Объединение племен",
			text = [=[Племя {link:arathi-highlands}Арати{/link} билось с Амани дольше любого другого, и Торадин учился войне на тролльем рубеже. Он видел то, чего не желали видеть другие вожди: тролли уничтожат племена одно за другим. Он собрал их воедино всеми средствами, какие имел. Одних он привлек браком, других — обещаниями земли и богатства, а третьих победил в бою. Побежденных он не унизил. Он сделал их вождей своими полководцами, и так они стали самыми верными его людьми.]=],
		},
		{
			title = "Стром",
			text = [=[Торадин поставил свою столицу на сухих равнинах нагорья, вдали от густых лесов, где тролли устраивали засады. Крепость {link:stromgarde-keep}Стром{/link} стала убежищем, и люди шли в нее со всего континента. Здесь же человечество впервые познало тайные искусства.]=],
		},
		{
			title = "Войны с троллями",
			text = [=[Когда Амани обрушились на {link:quel-thalas}Кель'Талас{/link}, эльфы отправили в {link:stromgarde-keep}Стром{/link} послов. Они обещали обучить сотню людей путям магии в обмен на мечи {link:arathor}Аратор{/link}а. Торадин согласился. Его войско ударило по троллям на юге эльфийских земель и увлекло их в предгорья {link:alterac-mountains}Альтерак{/link}ских гор, где эльфы и новые маги людей обрушились на них с другой стороны. Амани были сломлены. В благодарность эльфы принесли клятву дружбы его роду.]=],
		},
		{
			title = "Наследие",
			text = [=[Торадин желал, чтобы {link:stromgarde-keep}Стром{/link} оставался сердцем его державы, и опасался слишком широко раскинувшейся империи. После него его народ все равно разошелся и основал {link:dalaran}Даларан{/link}, {link:gilneas}Гилнеас{/link}, {link:kul-tiras}Кул Тирас{/link}, {link:alterac-mountains}Альтерак{/link} и Лордерон. Стром пришел в упадок. {link:nak}Нак{/link}онец последние из его рода покинули город и отплыли на юг, чтобы основать новое королевство. Много веков спустя {link:anduin-lothar}Андуин Лотар{/link}, последний из этой линии, возглавил {link:alliance}Альянс{/link} {link:lordaeron}Лордерона{/link} во Второй войне.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Хроники мало говорят о его собственной семье, о его последних годах и о его смерти. Эта запись не строит о них догадок.]=],
		},
	},
	chapters = {
		{
			title = "Печать Торадина",
			hint = [=[Проследите путь разбитой печати, которая носит имя первого короля.]=],
			text = [=[Среди печатей, стерегущих гробницу рода Троллебоев, есть одна, названная в честь первого короля, — Печать Торадина. Принц {link:prince-galen-trollbane}Гален{/link} разбил ее и раздал куски своим последним защитникам. Куски сняли с их тел, и тролль-шаман Орды вновь соединил их в целое. Имя первого короля стало ключом в руках троллей, которых некогда победил его народ.]=],
		},
	},
	mentions = {
		{ text = "«Разбитая печать»" },
		{ text = "«Печать Торадина»" },
	},
	bonds = {
		{ id = "arathor", name = "Аратор", note = "народ, который он основал" },
		{ id = "anduin-lothar", name = "Андуин Лотар", note = "последний из его рода" },
		{ id = "thoradin-s-wall", name = "Стена Торадина", note = "носит его имя" },
		{ id = "stromgarde-keep", name = "Крепость Стромгард", note = "некогда его столица, Стром" },
	},
})

