		{
			title = "Обзор",
			text = [=[Торас Троллебой был королем {link:stromgarde-keep}Стромгард{/link}а, наследником древнего дома, что правит городом с тех пор, как его покинул королевский род {link:arathor}Аратор{/link}а. Он был королем-воином в краю суровых солдат. Теперь он мертв, и его королевство умерло вместе с ним. Он лежит в запечатанной гробнице в Святилище за часовней Стромгарда, и рядом с ним — меч его дома.]=],
		},
		{
			title = "Значение",
			text = [=[Торас был одним из правителей, поднявших {link:alliance}Альянс{/link} {link:lordaeron}Лордерона{/link} против Орды. Его дом ведет род от полководца Войн с троллями Игнея, чей клинок {link:trol-kalar}Трол'калар{/link} дал семье ее имя. Для троллей {link:azeroth}Азерот{/link}а имя Троллебой по сей день — проклятие.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он привел {link:stromgarde-keep}Стромгард{/link} в {link:alliance}Альянс Лордерона{/link} во {link:second-war}Второй войне{/link}.
• После войны, когда Альянс перессорился из-за лагерей для интернированных и расходов на них, он вывел Стромгард из союза.
• Его похоронили с мечом {link:trol-kalar}Трол'калар{/link}, который носил Игней.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна летопись этих дней не сообщает, как умер Торас Троллебой. Его народ говорит лишь, что его больше нет.]=],
		},
	},
	chapters = {
		{
			title = "Гробница в Святилище",
			hint = "Встаньте перед гробницей последнего короля Стромгарда.",
			text = [=[{link:the-sepulcher}Гробница{/link} короля лежит за часовней квартала защитников, и за ней присматривают смотрители дома. Ее лицевая сторона покрыта резными линиями, и ничья рука не откроет их без печатей, которые рассеял его сын. В хватке каменных рук на гробнице лежит {link:trol-kalar}Трол'калар{/link}.]=],
		},
	},
	mentions = {
		{ text = "«Троллебой», весть о его смерти" },
		{ text = "«{link:trol-kalar}Трол'калар{/link}»" },
	},
	bonds = {
		{ id = "prince-galen-trollbane", name = "Принц Гален Троллебой", note = "его сын" },
		{ id = "terenas-menethil", name = "Теренас Менетил", note = "его союзник в Альянсе" },
		{ id = "trol-kalar", name = "Трол'калар", note = "меч его дома" },
	},
})

Translate("ruRU", "trol-kalar", {
	title = "Трол'калар",
	sections = {
		{
			title = "Обзор",
			text = [=[Трол'калар — древний меч дома Троллебоев. Его имя означает «убийца троллей» на языке самих троллей. В войнах {link:arathor}Аратор{/link}а его носил лорд Игней из {link:stromgarde-keep}Стром{/link}а, самый грозный враг, с каким когда-либо сталкивались тролли, и меч дал его дому имя.]=],
		},
		{
			title = "Гробница",
			text = [=[Когда {link:thoras-trollbane}король Торас{/link} умер, Трол'калар положили в его гробницу в Святилище за часовней {link:stromgarde-keep}Стромгард{/link}а, в хватку каменных рук. Гробницу запечатали оберегами, что отзываются только на печать. Принц {link:prince-galen-trollbane}Гален{/link} разделил эту печать на четыре: Печать Строма, Печать {link:thoradin}Торадин{/link}а, Печать {link:arathor}Аратор{/link}а и Печать Троллебоя. Одна досталась {link:syndicate}Синдикату{/link} вместе с городом. Остальные он отдал своим солдатам, командиру своей конницы и оставил себе. Собранные вместе, четыре становятся одной — это Печать Игнея.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:vol-jin}Вол'джин{/link} из {link:darkspear-trolls}племени Черного Копья{/link} хочет получить этот меч. Он послал охотника {link:zengu}Зенгу{/link} в {link:hammerfall}Павший Молот{/link} забрать его, чтобы убийцу троллей из {link:stromgarde-keep}Стром{/link}а обратить против троллей Гурубаши из {link:zul-gurub}Зул'Гуруба{/link}.]=],
		},
	},
})

Translate("ruRU", "witherbark-trolls", {
	title = "Тролли племени Сухокожих",
	aliases = { "Сухокожие", "тролли Сухокожих", "племя Сухокожих" },
	sections = {
		{
			title = "Обзор",
			text = [=[Сухокожие — племя лесных {link:trolls}троллей{/link}, что живет на юго-востоке Нагорья {link:arathi-highlands}Арати{/link}. Их деревня стоит там среди холмов, а за ней лежат пещеры, где собираются предводители их боевых отрядов. Тролли воюют с людьми {link:stromgarde-keep}Стром{/link}а со времен, когда правил {link:thoradin}Торадин{/link}, и Сухокожие до сих пор хранят эту войну в сердце.]=],
		},
		{
			title = "Их обычаи",
			text = [=[В племени есть метатели топоров, охотники за головами, берсерки и знахари, что носят сумки с лекарствами и амулеты из кровавого камня. Его темным охотникам вручают особый нож, когда они завершают обряды посвящения. Два предводителя боевых отрядов, Залас Сухокожий и Нимар Убийца, ведут их на войну.]=],
		},
		{
			title = "Наши дни",
			text = [=[Сухокожие когда-то сражались рядом с {link:orcs}орк{/link}ами, а потом покинули их. Теперь они объединились с {link:ogres}огр{/link}ами Тяжелого Кулака, чтобы выгнать Орду из Павшего Молота. Их бойцы делят с ограми холм {link:boulder-gor}Камен'гор{/link}, а берсерки племени стоят рядом с ограми в руинах {link:stromgarde-keep}Стромгард{/link}а. {link:drum-fel}Драм Фел{/link} из Павшего Молота сделал их первой целью своей войны.]=],
		},
	},
})

Translate("ruRU", "boulderfist-ogres", {
	title = "Огры Тяжелого Кулака",
	aliases = { "Тяжелый Кулак", "огры клана Тяжелого Кулака", "клан Тяжелого Кулака" },
	sections = {
		{
			title = "Обзор",
			text = [=[Тяжелый Кулак — величайший клан {link:ogres}огров{/link} на {link:arathi-highlands}Нагорье Арати{/link}. Они удерживают холм {link:boulder-gor}Камен'гор{/link}, пещеры Крепости Тяжелого Кулака и большую часть разрушенного города {link:stromgarde-keep}Стромгард{/link}а. Ни одна летопись не сообщает, когда они пришли на нагорье.]=],
		},
		{
			title = "Их обычаи",
			text = [=[Это громилы, каратели, крушители и лорды, а с ними маги и шаманы, которые научились пользоваться награбленными сокровищами. Их шаманы ценят лазурные агаты, взятые из Башни {link:arathor}Аратор{/link}а. В Крепости Тяжелого Кулака {link:ogres}огр{/link}-маг {link:kor-gresh-coldrage}Кор'греш Холодная Ярость{/link} мечет лед из украденного жезла. В {link:stromgarde-keep}Стромгард{/link}е ими командует огр {link:or-kalar}Ор'Калар{/link} от имени полководца {link:mug-thol}Маг'тол{/link}а, который сам не с нагорья.]=],
		},
		{
			title = "Наши дни",
			text = [=[Огры Тяжелого Кулака бьются с солдатами {link:stromgarde-keep}Стромгард{/link}а и с {link:syndicate}Синдикат{/link}ом за руины города, и они объединились с троллями племени Сухокожих против Павшего Молота. Среди их вожаков страх внушают Ков{link:orcs}орк{/link}, Молок Сокрушитель, {link:ruul-eagletalon}Руул{/link} Один Камень и Гнилобрюх.]=],
		},
	},
})

Translate("ruRU", "drywhisker-kobolds", {
	title = "Кобольды-Сухоусы",
	aliases = { "Сухоусы", "кобольды племени Сухоусов" },
	sections = {
		{
			title = "Обзор",
			text = [=[Сухоусы — племя {link:kobolds}кобольдов{/link}, что роет землю в Теснине Сухоусов, на дальнем северо-востоке нагорья. Это землемеры и копатели, и среди них трудится геомант Кремневый {link:kinelory}Кин{/link}жал, повелевающий огнем.]=],
		},
		{
			title = "Осколки",
			text = [=[Сухоусы не только рудокопы. Глубоко в своей теснине они стерегут гроздь переливчатых осколков кристалла и носят с собой частицы странной силы. Существо, что лежит связанным под нагорьем, называет их союзниками великанов, которые ее держат. Трое из них ходят рядом с самим каменным стражем {link:fozruk}Фозрук{/link}ом. Никто не знает, что великаны дали {link:kobolds}кобольд{/link}ам за службу и понимают ли кобольды вообще, кому служат.]=],
		},
	},
})

Translate("ruRU", "league-of-arathor", {
	title = "Лига Аратора",
	sections = {
		{
			title = "Обзор",
			text = [=[Лига Аратора — боевая сила того, что осталось от королевства {link:stromgarde-keep}Стромгард{/link}. Ее солдаты — наследники гордой державы, чью столицу ныне удерживают {link:ogres}огр{/link}ы и разбойники. Они поклялись отвоевать нагорье для народа Стромгарда и для {link:alliance}Альянса{/link}.]=],
		},
		{
			title = "Их дело",
			text = [=[Лига стоит лагерем в Опорном пункте под началом фельдмаршала {link:field-marshal-oslight}Ослайт{/link}а. Ее первая битва — за Низину {link:arathi-highlands}Арати{/link}, плодородную долину ферм, рудников, кузниц и лесов. Лига намерена добыть богатства низины для своих союзников в {link:stormwind-city}Штормград{/link}е, а через Штормград — для всего {link:alliance}Альянс{/link}а. Ее солдаты удерживают Зал Троллебоя на краю долины, названный в честь королевского дома {link:stromgarde-keep}Стромгард{/link}а.]=],
		},
		{
			title = "Наши дни",
			text = [=[В низине Лиге противостоят {link:defilers}Осквернители{/link} из числа Отрекшихся. Ее интендант, Сэмюэл Хоук, шлет провизию тем, кто сражается, а ее сержанты призывают каждого солдата бить прежде, чем ударит враг.]=],
		},
	},
})

Translate("ruRU", "defilers", {
	title = "Осквернители",
	aliases = { "Осквернители Отрекшихся" },
	sections = {
		{
			title = "Обзор",
			text = [=[Осквернители — отборные войска {link:forsaken}Отрекшихся{/link}, посланные на {link:arathi-highlands}Нагорье Арати{/link} под бдительным оком повелителя ужаса: за ними следит {link:varimathras}Вариматас{/link}. Они бьются с Лигой {link:arathor}Аратор{/link}а за Низину Арати. Их цель — не война {link:orcs}орк{/link}ов, а война их собственной королевы: отрезать людей севера от их союзников-{link:dwarves}дворф{/link}ов на юге и захватить богатства низины для {link:undercity}Подгород{/link}а.]=],
		},
		{
			title = "Их лагерь",
			text = [=[Штаб Осквернителей находится в Павшем Молоте, рядом с {link:orcs}орк{/link}ами и троллями заставы, под началом владыки смерти {link:deathmaster-dwire}Двайр{/link}а. В низине они удерживают Логово Осквернителя. Их интендант, Резерфорд Твинг, шлет провизию тем, кто сражается за них, а при командире служит ловчий смерти Мортис.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:deathmaster-dwire}Двайр{/link} считает, что даже маленький лагерь в Опорном пункте однажды может стать угрозой для Орды. Осквернители намерены позаботиться о том, чтобы {link:arathi-highlands}Арати{/link} никогда больше не стало домом для людей.]=],
		},
	},
})
